функция safeParseRoles(maybe) {
 if (!maybe) возвращает null;
 if (typeof maybe === 'object') возвращает maybe;
 if (typeof maybe === 'string') {
 try { return JSON.parse(maybe); } catch (e) { return null; }
 }
 return null;
}

функция extractText(field) {
 if (!field) return "" ;
 if (поле typeof === "строка") return field;
 if (Array.isArray(field)) return field.map(x => (typeof x === "строка" ? x : JSON.stringify(x))).join("\n");
 try { return JSON.stringify(field); } catch (e) { return ""; }
}

